import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        url_legacy_compatible = url.find('.example.com') > 0
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(url, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException:
        return []

    soup = BeautifulSoup(response.text, 'html.parser')
    script_tags = soup.find_all('script')

    dictionaries = []
    for script in script_tags:
        script_content = script.string
        if script_content:
            try:
                evaluated_content = ast.literal_eval(script_content)
                if isinstance(evaluated_content, dict):
                    dictionaries.append(evaluated_content)
            except (ValueError, SyntaxError):
                continue
    return dictionaries

