import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP request failed: {e}")

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')

    if not rows:
        return pd.DataFrame()

    headers = []
    header_row = rows[0].find_all(['th', 'td'])
    if header_row and rows[0].find('th'):
        headers = [th.text.strip() for th in rows[0].find_all('th')]
        data_rows = rows[1:]
    else:
        data_rows = rows

    data = []
    for row in data_rows:
        cols = row.find_all('td')
        cols = [ele.text.strip() for ele in cols]
        data.append(cols)

    if not headers and data:
        num_cols = len(data[0]) if data else 0
        headers = [f'col_{i}' for i in range(num_cols)]
    elif not headers and not data:
        return pd.DataFrame()

    df = pd.DataFrame(data, columns=headers)
    return df

