import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to connect to the API: {e}")

    if not response.content:
        return {}

    decoded_content = None
    if from_encoding:
        decoded_content = response.content.decode(from_encoding)
    else:
        detection = chardet.detect(response.content)
        if detection and detection['encoding']:
            decoded_content = response.content.decode(detection['encoding'])
        else:
            raise ValueError("Unable to detect encoding for non-empty content")

    re_encoded_content = decoded_content.encode(to_encoding)
    return json.loads(re_encoded_content)

