import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url or not destination_directory:
        raise ValueError("URL and destination_directory must be non-empty strings.")

    if headers is None:
        headers = {'User-Agent': 'Mozilla/5.0'}

    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to download the zip file from {url}: {e}")

    os.makedirs(destination_directory, exist_ok=True)

    zip_path = os.path.join(destination_directory, "downloaded.zip")
    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        raise IOError(f"Failed to save the zip file to {zip_path}: {e}")

    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = [os.path.join(destination_directory, name) for name in zip_ref.namelist()]
    except zipfile.BadZipFile as e:
        raise ValueError(f"Downloaded file is not a valid zip file: {e}")
    except Exception as e:
        raise IOError(f"Failed to extract zip file contents: {e}")
    finally:
        if os.path.exists(zip_path):
            os.remove(zip_path)

    return extracted_files

